job<-fread(file.path(OUT,'02_CellChat_highlow/job_manifest.csv'));db<-fread(file.path(OUT,'00_input_audit/CellChatDB_interactions.csv'));keys<-c('method','min_cells','kind','feature','direction','partner')
stat<-function(hi,lo,diff,ds){n<-length(diff);if(!any(hi>0|lo>0))return(list(n_patients=n,nonzero_difference_patients=0L,positive_either_patients=0L,positive_datasets=0L,high_median=0,low_median=0,difference_median=0,difference_mean=0,CI_low=if(n>=5)0 else NA_real_,CI_high=if(n>=5)0 else NA_real_,positive_high_patients=0L,positive_low_patients=0L,high_prevalence=0,low_prevalence=0,high_greater_fraction=0,p=if(n>=5)1 else NA_real_,status=if(n<5)'insufficient_patients'else 'exploratory_patient_test'));nonzero<-any(diff!=0);ci<-if(n>=5&&nonzero)quantile(matrixStats::colMedians(matrix(sample(diff,2000*n,TRUE),nrow=n)),c(.025,.975))else if(n>=5)c(0,0)else c(NA_real_,NA_real_);list(n_patients=n,nonzero_difference_patients=sum(diff!=0),positive_either_patients=sum(hi>0|lo>0),positive_datasets=uniqueN(ds[hi>0|lo>0]),high_median=median(hi),low_median=median(lo),difference_median=median(diff),difference_mean=mean(diff),CI_low=ci[1],CI_high=ci[2],positive_high_patients=sum(hi>0),positive_low_patients=sum(lo>0),high_prevalence=mean(hi>0),low_prevalence=mean(lo>0),high_greater_fraction=mean(diff>0),p=if(n<5)NA_real_ else if(!nonzero)1 else suppressWarnings(wilcox.test(diff,exact=FALSE)$p.value),status=if(n<5)'insufficient_patients'else 'exploratory_patient_test')}
for(method_current in unique(job$method))for(th in c(5,10,20,30)){
 method<-method_current;tag<-paste0(method,'_t',th);done<-file.path(OUT,'03_patient_level_comparison',paste0(tag,'_DONE.csv'));if(file.exists(done))next
 jj<-job[method==method_current&runnable==TRUE];paths<-file.path(OUT,'02_CellChat_highlow',jj$job_id,paste0('threshold',th,'.csv.gz'));if(!all(file.exists(paths)))stop('Incomplete jobs for ',tag)
 set.seed(123L+100L*match(method_current,unique(job$method))+as.integer(th));cat('SUMMARY',tag,'\n');flush.console();dat<-rbindlist(lapply(paths,fread));dat<-dat[eligible==TRUE];if(!nrow(dat)){writecsv(data.table(method=method,min_cells=th,status='NO_PAIRED_ELIGIBLE_SPECIMENS'),done);next}
 ids<-c(keys,'specimen_id','patient_id','dataset','clinical_group');wide<-dcast(dat,as.formula(paste(paste(ids,collapse='+'),'~state')),value.var='strength');stopifnot(!anyNA(wide$high),!anyNA(wide$low));wide[,difference:=high-low]
 # Sum LR probabilities by the database's actual annotation to distinguish ECM, secreted, contact and non-protein signals.
 cats<-merge(wide[kind=='LR'],db[,.(feature=interaction_id,signal_category=annotation)],by='feature',all.x=TRUE);stopifnot(!anyNA(cats$signal_category));cats<-cats[,.(high=sum(high),low=sum(low),difference=sum(difference)),by=c(setdiff(ids,c('feature','kind')),'signal_category')];setnames(cats,'signal_category','feature');cats[,kind:='category'];wide<-rbindlist(list(wide,cats),use.names=TRUE)
 # Totals use precisely the same eligible partners for both states, excluding high-low and self.
 total<-wide[kind%in%c('network','interaction_count','category'),.(high=sum(high),low=sum(low),difference=sum(difference),eligible_partners=.N),by=c(setdiff(ids,'partner'))];total[,partner:='TOTAL'];wide[,eligible_partners:=1L];wide<-rbindlist(list(wide,total),use.names=TRUE,fill=TRUE);fwrite(wide,file.path(OUT,'03_patient_level_comparison',paste0(tag,'_specimen_pairs.csv.gz')),na='NA',compress='gzip')
 wide[,analysis_condition:=ifelse(clinical_group=='Normal','Normal','Tumor')];pat<-wide[,.(high=median(high),low=median(low),difference=median(difference),eligible_specimens=.N,partner_count_median=median(eligible_partners)),by=c(keys,'patient_id','dataset','analysis_condition')];fwrite(pat,file.path(OUT,'03_patient_level_comparison',paste0(tag,'_patient_pairs.csv.gz')),na='NA',compress='gzip')
 all<-rbindlist(c(list(copy(pat[analysis_condition=='Tumor'])[,stratum:='Tumor_ALL'],copy(pat[analysis_condition=='Normal'])[,stratum:='Normal']),lapply(unique(pat[analysis_condition=='Tumor',dataset]),function(ds)copy(pat[analysis_condition=='Tumor'&dataset==ds])[,stratum:=paste0('dataset:',ds)]),lapply(unique(pat[analysis_condition=='Tumor',dataset]),function(ds)copy(pat[analysis_condition=='Tumor'&dataset!=ds])[,stratum:=paste0('exclude:',ds)])))
 su<-all[,stat(high,low,difference,dataset),by=c(keys,'stratum')];su[,FDR:=p.adjust(p,'BH'),by=.(method,min_cells,kind,direction,stratum)];ann<-db[,.(feature=interaction_id,ligand,receptor,pathway=pathway_name,annotation)];su<-merge(su,ann,by='feature',all.x=TRUE,sort=FALSE);fwrite(su,file.path(OUT,'04_pathway_LR_analysis',paste0(tag,'_statistics.csv.gz')),na='NA',compress='gzip');writecsv(data.table(method=method,min_cells=th,status='SUCCESS',specimens=uniqueN(wide$specimen_id),tumor_patients=uniqueN(pat[analysis_condition=='Tumor',patient_id])),done);rm(dat,wide,pat,all,su);gc(FALSE)
}
